import os
from .factory import PrismaFactory
from .provider import PrismaProvider
import taf.internal.robot_typecasts as robot_typecasts


class prisma:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, testline_configuration=None):
        self._prisma_provider = PrismaProvider()
        self._prisma_factory = PrismaFactory()
        if 'PRISMA_CONFIG_PATH' in os.environ:
            self.load_config(os.environ['PRISMA_CONFIG_PATH'], testline_configuration)

    def load_config(self, yaml_file, testline_configuration):
        """
        load yaml file for configuring the prisma
        :param yaml_file: yaml file full path name
        :param object: testline config object, generated by taf.config.testline.ue.prisma(...)
        """
        config = self._prisma_provider.load(yaml_file, testline_configuration)
        self.prisma = self._prisma_factory.create(self._prisma_provider.config)
        return config

    def setup(self):
        """
        prisma setup, will create connect session to lsu and airmosaic
        """
        self.prisma.setup()

    def teardown(self):
        """
        prisma teardown, will disconnect to lsu and airmosaic
        """
        self.prisma.teardown()

    def start_lsu(self, node_name, timeout=100):
        """
        run lsustart script in yaml to start
        :param node_name: indicates the lsu device, such as lsu_s1, lsu_x2uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns output after running the script
        """
        return self.prisma.start_lsu(node_name, timeout)

    def stop_lsu(self, node_name, timeout=30):
        """
        run lsustop script in yaml to stop lsu
        :param node_name: indicates the lsu device, such as lsu_s1, lsu_x2uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns output after running the script
        """
        return self.prisma.stop_lsu(node_name, timeout)

    def clean_lsu(self, node_name, timeout=30):
        """
        run lsuclean script in yaml to clean lsu
        :param node_name: indicates the lsu device, such as lsu_s1, lsu_x2uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns output after running the script
        """
        return self.prisma.clean_lsu(node_name, timeout)

    def create_5g_cell(self, node_name, timeout=30):
        """
        run script in yaml to create 5g cell
        :param node_name: indicates the lsu device, such as lsu_x2uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns output after running the script
        """
        return self.prisma.create_5g_cell(node_name, timeout)

    def create_4g_cell(self, node_name, timeout=30):
        """
        run script in yaml to create 4g cell
        :param node_name: indicates the lsu device, such as lsu_x2uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns output after running the script
        """
        return self.prisma.create_4g_cell(node_name, timeout)

    def get_4g_cell_id(self, node_name, timeout=30):
        """
         run script in yaml to get 4g cell id
        :param node_name: indicates the lsu device, such as lsu_x2uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns cell id
        """
        return self.prisma.get_4g_cell_id(node_name, timeout)

    def get_5g_cell_id(self, node_name, timeout=30):
        """
         run script in yaml to get 5g cell id
        :param node_name: indicates the lsu device, such as lsu_x2uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns cell id
        """
        return self.prisma.get_5g_cell_id(node_name, timeout)

    def start_epc(self, node_name, timeout=30):
        """
        run start_epc script in yaml at the backend, will wait for message
        from other command
        :param node_name: indicates the lsu device, such as lsu_s1,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        """
        self.prisma.start_epc(node_name, timeout)

    def init_epc(self, node_name, timeout=30):
        """
        run init_epc script in yaml at the backend, will wait for message
        from other command
        :param node_name: indicates the lsu device, such as lsu_s1,
        :param timeout: seconds, when time out, force exit from execute
        """
        self.prisma.init_epc(node_name, timeout)

    def get_epc_log(self, node_name, expected_regex='', timeout=30):
        """
        run get_epc_log script in yaml to get the log on start_epc session
        :param node_name: indicates the lsu device, such as lsu_s1,
        which is predefined in the yaml file
        :param expected_regex: regex string to do match in the epc log, if matched
        exit from call
        :param timeout: seconds, when timeout, exit from call
        :return: Returns output until the matched line after running the script
        """
        return self.prisma.get_epc_log(node_name, expected_regex, timeout)

    def clean_epc_log(self, node_name, timeout=30):
        """
        run clean_epc_log script in yaml to clean the log from start_epc session
        :param node_name: indicates the lsu device, such as lsu_s1,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        """
        self.prisma.clean_epc_log(node_name, timeout)

    def stop_epc(self, node_name, timeout=30):
        """
        run stop_epc script in yaml to kill the epc
        :param node_name: indicates the lsu device, such as lsu_s1,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        """
        self.prisma.stop_epc(node_name, timeout)

    def get_ra_status(self, node_name, timeout=30):
        """
        run get_ra_status script in yaml to get random access status
        :param node_name: indicates the lsu device, such as lsu_uu,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns output after running the script
        """
        return self.prisma.get_ra_status(node_name, timeout)

    def start_tstm(self, node_name, timeout=30):
        """
        run start_tstm script in yaml to start test manager server
        :param node_name: indicates the lsu device, such as lsu_uu or lsu_s1,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        """
        self.prisma.start_tstm(node_name, timeout)

    def stop_tstm(self, node_name, timeout=30):
        """
        run script in yaml to force kill the tstm relevant processes
        :param node_name: indicates the lsu device, such as lsu_uu or lsu_s1,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        """
        self.prisma.stop_tstm(node_name, timeout)

    def clean_tstm_log(self, node_name, timeout=30):
        """
        run command in yaml to force clean the tstm log if the tstm run in back-end
        :param node_name: indicates the lsu device, such as lsu_uu or lsu_s1,
        which is predefined in the yaml file
        :param timeout: seconds, when time out, force exit from execute
        """
        self.prisma.clean_tstm_log(node_name, timeout)

    def get_tstm_log(self, node_name, expected_regex='', timeout=30):
        """
        run command in yaml to get the tstm log cause the tstm run in back-end or
        a persistent channel
        :param node_name: indicates the lsu device, such as lsu_uu or lsu_s1,
        which is predefined in the yaml file
        :param expected_regex: regex template to be matched, once matched, call exit
        :param timeout: seconds, when time out, force exit from execute
        :return: Returns output after running the script
        """
        return self.prisma.get_tstm_log(node_name, expected_regex, timeout)

    def start_mosaic(self, node_name='airmosaic'):
        """
        start airmosaic remotely with the command specified in yaml
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        """
        return self.prisma.start_mosaic(node_name)

    def close_mosaic(self, node_name='airmosaic'):
        """
        run rest api to close airmosaic
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        """
        self.prisma.close_mosaic(node_name)

    def prepare_test(self, sid, config_dir, timeout=30, node_name='airmosaic'):
        """
        run rest apis to load config folder, sid and connect to tstm to be ready
        for run scenario
        which is predefined in the yaml file
        :param sid: sid file name in the config directory
        :param config_dir: folder containing all the airmosaic scenario releveant
        files, such as *.sid, *.sce, *.usr *.mdl
        :param timeout: timeout for status check, once status cannot reach matched
        out of the timeout, function call will exit with an exception
        :param node_name: indicates the airmosaic device,
        """
        self.prisma.prepare_test(node_name,
                                 sid,
                                 config_dir,
                                 timeout)

    def stop_test_running(self, node_name='airmosaic'):
        """
        run rest api to stop the testing and disconnect to test manager
        :param node_name: indicates the airmosaic device
        """
        self.prisma.stop_test_manager(node_name)

    def clear_test(self, node_name='airmosaic'):
        """
        close the session and temporary config zip file when all scenarios done
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        """
        self.prisma.clear_test(node_name)

    def ue_attach(self, node_name='airmosaic', wait_for_complete=False, timeout=120):
        """
        run rest api to call attach sce file specified in yaml
        :param node_name: indicates the airmosaic device,
        :param wait_for_complete: set whether wait for the execution completed
        :param timeout: if wait_for_complete is set True, execution will be forced
        exit when timeout
        which is predefined in the yaml file
        """
        self.prisma.attach(node_name, wait_for_complete, timeout)

    def ue_detach(self, node_name='airmosaic', wait_for_complete=False, timeout=120):
        """
        run rest api to call dettach sce file specified in yaml
        :param node_name: indicates the airmosaic device
        which is predefined in the yaml file
        :param wait_for_complete: set whether wait for the execution completed
        :param timeout: if wait_for_complete is set True, execution will be forced
        exit when timeout
        :return: Returns output after running the script
        """
        self.prisma.detach(node_name, wait_for_complete, timeout)

    def traffic_start(self, node_name='airmosaic', wait_for_complete=False, timeout=120):
        """
        run rest api to call start traffic sce file specified in yaml
        :param node_name: indicates the airmosaic device
        :param wait_for_complete: set whether wait for the execution completed
        :param timeout: if wait_for_complete is set True, execution will be forced
        exit when timeout
        which is predefined in the yaml file
        """
        self.prisma.start_traffic(node_name, wait_for_complete, timeout)

    def traffic_stop(self, node_name='airmosaic', wait_for_complete=False, timeout=120):
        """
        run rest api to call stop traffic sce file specified in yaml
        :param node_name: indicates the airmosaic device
        :param wait_for_complete: set whether wait for the execution completed
        :param timeout: if wait_for_complete is set True, execution will be forced
        exit when timeout
        which is predefined in the yaml file
        """
        self.prisma.stop_traffic(node_name, wait_for_complete, timeout)

    def get_scenario_status(self, node_name='airmosaic'):
        """
        run rest api to get scenario status from airmosaic
        :return: status, optionals
                NONE, SIMINIT_AVAILABLE_INVALID, SIMINIT_AVAILABLE,
                RUNNING_SIMINIT, RUNNING_SIMINIT_SCEAVAIL, SIMINIT_COMPLETED,
                SCENARIO_AVAILABLE, SCENARIO_RUNNABLE,
                RUNNING_SCENARIO, SCENARIO_COMPLETED, ABNORMAL_FAIL, SID_OPENING
        """
        return self.prisma.get_status(node_name)

    def get_cell_status(self, node_name='airmosaic'):
        """
        run rest api to get cell status from airmosaic
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        :return: cell status is like [{"id":btsId,"status":status}.....]
        """
        return self.prisma.get_cell_status(node_name)

    def get_scenario_logger(self, output_file=None, node_name='airmosaic'):
        """
        run rest api to get scenario log
        :param output_file: if set, the file will be saved in the 'output_file' path
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        :return: array of formated structure,
        [{'recordId': record, 'datetime': datetime,
                'instance': instance, 'messageLevel': messageLevel,
                'category': category, 'message': message, 'group': group},
        """
        return self.prisma.get_scenario_logger(node_name, output_file=output_file)

    def get_test_result(self, node_name='airmosaic'):
        """
        run rest api to get test result
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        :return: test result is an XML string containing
                a summary of the test execution result.
        """
        return self.prisma.get_test_result(node_name)

    def get_bug_report(self, output_file=None, node_name='airmosaic'):
        """
        run rest api to get bug report
        :param output_file: if set, the file will be saved in the 'output_file' path
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        :return: zip file content
        """
        return self.prisma.get_bug_report(node_name, output_file=output_file)

    def get_log_counters(self, output_file=None, node_name='airmosaic'):
        """
        run rest api to get a zip compressed archive containing the csv files
        where the counters were saved
        :param output_file: if set, the file will be saved in the 'output_file' path
        :param node_name: indicates the airmosaic device,
        which is predefined in the yaml file
        :return: the zip file content
        """
        return self.prisma.get_log_counters(node_name, output_file=output_file)

    def execute_script(self, node_name, script_cmd, expect_regex='', timeout=30):
        """
        run specified command directly on the specified node defined in yaml file
        :param node_name: indicates the devices the script running on such as
        airmosaic, lsu, tstm which is predefined in the yaml file
        :param script_cmd: the command to be run
        :param expect_regex: the string to be matched in the output, once match,
        the call will exit
        :param timeout: when expect_regex is passed, timeout will lead call exit
        when cannot match the expect_regex
        :return: output from the script running
        """
        timeout = robot_typecasts.time_to_seconds(timeout)
        return self.prisma.execute_script(node_name, script_cmd, expect_regex, timeout)

    def execute_test(self, sce, node_name='airmosaic'):
        """
        run specified sce file directly on the specified node defined in yaml file
        :param sce: the scenario file name to be run
        :param node_name: indicates the devices the script running on such as
        airmosaic
        :return: output from the sce running
        """
        return self.prisma.execute_test(node_name, sce)

    def upload_file(self, node_name, local_path, remote_path):
        """
        upload local file to remote node
        :param node_name: indicates the devices the script running on such as
        airmosaic
        :param local_path: local file path
        :param remote_path: remote file path
        :return: execute output
        """
        return self.prisma.upload_file(node_name, local_path, remote_path)

    def download_file(self, node_name, remote_path, local_path):
        """
        download remote node to local file
        :param node_name: indicates the devices the script running on such as
        airmosaic
        :param remote_path: remote file path
        :param local_path: local file path
        :return: execute output
        """
        return self.prisma.download_file(node_name, remote_path, local_path)

    def add_counters(self, counters, node_name='airmosaic'):
        """
        Register counters to be collected during test execution by airmosaic through harness api
        :param counters: a list of dictionaries each identifying a specific
        counter to be collected:
                        [{'category':category, 'instance':instance, 'name':name},...]
        :param node_name: indicates the devices the script running on such as
        airmosaic
        :return: list of addedCounters after add_counters executed:
                 [{'category':category, 'instance':instance, 'name':name},...]
        """
        return self.prisma.add_counters(node_name, counters)

    def get_counters(self, node_name='airmosaic'):
        """
        get the current value of the registered counters
        :param node_name: indicates the devices the script running on such as
        airmosaic
        :return: all the registered counters, each with its current value:
                [{'category':category, 'instance':instance, 'name':name, 'value':value},...]

        """
        return self.prisma.get_counters(node_name)
